const hora = startISO.slice(11, 16);
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !/^\d{2}:\d{2}$/.test(hora)) {
  console.log('MQL IA: sin fecha/hora de cita — no se manda');
  return [];
