// Nodo Code «Confirmar MQL IA» del workflow
// «Clinera — Google Meet por profesional» (id FZvyK42lkQdKWcIl).
// Cuelga de «Meta CAPI - MQL (IA)».
//
// Marca el ledger SOLO si Meta aceptó de verdad (events_received > 0 y
// sin error). El nodo del CAPI corre con neverError: un 400 llega como
// item normal. Marcarlo acá ante cualquier respuesta perdería el evento
// para siempre.
//
// El ledger se lee tolerando objeto o string, y se escribe REASIGNANDO
// el objeto entero en la clave de primer nivel — nunca
// ledger.mqlAgenteIa[id] = …, porque el detector de cambios de n8n es
// un proxy sobre el objeto de primer nivel.

const ledger = $getWorkflowStaticData('global');
const bruto = ledger.mqlAgenteIa;
const enviados = typeof bruto === 'string' ? JSON.parse(bruto)
               : (bruto && typeof bruto === 'object' ? bruto : {});

const ok = [];
const fallidos = [];

for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const previo = $('Preparar MQL Agente IA').all()[i]?.json || {};
  const id = previo.event_id;
  if (!id) continue;
  const aceptado = Number(resp.events_received || 0) > 0 && !resp.error;
  if (aceptado) {
    enviados[id] = new Date().toISOString();
    ok.push(id);
  } else {
    fallidos.push({ id: id, error: resp.error || resp });
  }
}

ledger.mqlAgenteIa = { ...enviados };

if (fallidos.length) {
  console.log('MQL IA rechazados por Meta (se reintentan en el próximo disparo): '
    + JSON.stringify(fallidos).slice(0, 800));
}
console.log('MQL IA confirmados: ' + ok.length + ' · fallidos: ' + fallidos.length
  + ' · ledger: ' + Object.keys(enviados).length);

return [{ json: { confirmados: ok.length, fallidos: fallidos.length, detalle: fallidos, ok: ok } }];
